parameters.jsCode:
const cfg = $('⚙️ Prepare Context').item.json;
const research = $('🔍 Research Agent').item.json.output || '';
const architecture = $('🏗️ Systems Architect Agent').item.json.output || '';
const roadmap = $input.first().json.output || '';

let sources = '_No structured sources returned — verify claims manually._';
const split = research.split(/###\s*SOURCES/i);
if (split.length > 1) sources = split[1].trim();

let researchSummary = research;
const summarySplit = research.split(/###\s*SOURCES/i);
if (summarySplit.length > 1) researchSummary = summarySplit[0].trim();

const finalMarkdown = `# Tech R&D Report: ${cfg.topic}

*Goal: ${cfg.goal} · Generated: ${cfg.timestamp}*

---

## 1. Research Findings

${researchSummary}

---

## 2. Architecture & Design

${architecture}

---

## 3. Build Roadmap

${roadmap}

---

## Sources

${sources}
`;

const wordCount = finalMarkdown.split(/\s+/).filter(Boolean).length;

return [{
  json: {
    topic: cfg.topic,
    goal: cfg.goal,
    generated_date: cfg.timestamp,
    word_count: wordCount,
    final_markdown: finalMarkdown
  }
}];
